  "exp": "正解は1(行政不服審査法22条1項)。同項は、教示された行政庁に書面で審査請求がされたときの当該行政庁の義務として、審査請求書を処分庁又は審査庁となるべき行政庁へ速やかに送付すること、及びその旨を審査請求人に通知することの二つを定めている。2: 法が定めるのは請求人への返付や再度の教示ではなく、行政庁間での送付と請求人への通知である(22条1項)。審査請求人に出し直しを求める仕組みではない。3: 22条1項の救済が働くのは「書面で審査請求がされたとき」であり、口頭による審査請求は同項の対象外である(なお審査請求は19条1項により原則として書面によることとされ、口頭によることができるのは他の法律に定めがある場合に限られる)。4: 22条5項は、審査請求書等が審査庁となるべき行政庁に送付されたときは「初めから」審査庁となるべき行政庁に審査請求がされたものとみなすと定めており、送付時を基準とするのではない。これにより審査請求期間の点でも請求人が救済される。5: 再調査の請求をすることができない処分につき誤って再調査の請求をすることができる旨を教示した場合(22条3項)は、処分庁は請求人の申立てを待たず、速やかに再調査の請求書又は再調査の請求録取書を審査庁となるべき行政庁に送付し、その旨を通知しなければならない。請求人からの申立てが要件となるのは、再調査の請求をすることができる処分につき審査請求もできる旨を教示しなかった場合(22条4項)である。",
